custom_css:
/* ==========================================================================
   DIIA · capa de marca
   Identidad: negro profundo + oro del logotipo, tipografía espaciada y limpia
   del portafolio (blanco, líneas finas, fotografía de arquitectura).
   Los marcadores SKY_A/B/C los sustituye make_site.py por SVG de skyline.
   ========================================================================== */

:root{--gold:#cfb565;--gold-deep:#a88a3d;--champagne:#ecdba2;--black:#070707}

/* --- Tonos: negro neutro (como el fondo del logo) y marfil cálido ---------- */
[data-tone="dark"]{--bg:#070707;--bg-rgb:7 7 7;--bg-2:#0d0c0a;--surface:#121110;--surface-2:#1a1814;--muted:#b4ab97}
[data-tone="light"],:root{--bg:#fbfaf6;--bg-rgb:251 250 246;--bg-2:#f3f0e7;--surface:#ffffff}
.sec--alt{background:var(--bg-2)}

/* --- Tipografía: Jost (geométrica, afín al logotipo) con aire ------------- */
h1,h2,h3,h4{font-weight:500}
h1{font-size:clamp(2.3rem,7vw + .3rem,5.1rem);letter-spacing:-.022em;line-height:1.05}
h2{font-size:clamp(1.85rem,3.8vw + .45rem,3.2rem);letter-spacing:-.018em;line-height:1.1}
h3{letter-spacing:.005em}
.lead,.hero__sub{font-weight:400;line-height:1.7}
.eyebrow{padding:0;border:0;border-radius:0;background:none;gap:1rem;font:500 .7rem/1.4 var(--font-display);letter-spacing:.3em;color:var(--primary-ink)}
.eyebrow::before{width:2.4rem;height:1px;border-radius:0;background:currentColor;box-shadow:none;transform-origin:left;animation:lineBreath 4.2s ease-in-out infinite alternate}
@keyframes lineBreath{from{transform:scaleX(.35);opacity:.55}to{transform:scaleX(1);opacity:1}}
@media (min-width:640px){.eyebrow{letter-spacing:.42em;font-size:.72rem}}

/* --- Botones: sobrios, mayúsculas con tracking ----------------------------- */
.btn{white-space:normal;text-align:center;line-height:1.25;padding:.85rem 1.5rem;font:600 .78rem/1.25 var(--font-display);letter-spacing:.14em;text-transform:uppercase}
.btn--lg{padding:.95rem 1.8rem}
.btn--sm{font-size:.72rem;padding:.7rem 1.1rem}
.btn--primary{background:linear-gradient(120deg,var(--gold),var(--champagne),var(--gold));background-size:200% 100%;color:#14110a}
.btn--ghost{border-color:rgb(var(--ink-rgb)/.3)}
.hero__ctas .btn{flex:1 1 100%}
@media (min-width:560px){.hero__ctas .btn{flex:0 0 auto}}

/* --- Loader: marca sobre negro, anillo dorado ------------------------------ */
.loader__mark{background:radial-gradient(circle at 50% 30%,#17140d,#050505);border:1px solid rgb(var(--glow-rgb)/.45);padding:15%;box-shadow:0 0 60px rgb(var(--glow-rgb)/.28),inset 0 0 22px rgb(var(--glow-rgb)/.12)}
.loader__ring{width:8.5rem;height:8.5rem}
.loader__mark,.core__mark{position:relative;overflow:hidden}
.loader__mark img,.core__mark img{position:absolute;inset:11%;width:78%;height:78%;object-fit:contain}
.loader__name{max-width:min(80vw,22rem);text-align:center;line-height:1.7;letter-spacing:.34em;font-weight:500;font-size:.68rem;color:var(--gold)}
.loader__bar{width:12rem}

/* --- Cabecera y logotipo ---------------------------------------------------- */
.brand img{height:3.5rem;width:auto;max-width:none;transition:height .5s var(--ease)}
.site-header.is-scrolled .brand img{height:3rem}
.nav a{letter-spacing:.02em}
@media (min-width:960px){.nav a{font:500 .72rem/1 var(--font-display);letter-spacing:.22em;text-transform:uppercase}}

/* --- Hero ------------------------------------------------------------------ */
.hero__sub{max-width:33rem}
.frame>img{height:auto;object-position:50% 30%}
.chip{border-radius:2px;font:500 .68rem/1.2 var(--font-display);letter-spacing:.14em;text-transform:uppercase;padding:.65rem .95rem}
.chip--2{right:-1%;white-space:normal;max-width:15rem}
.hero__badges li{font-size:.82rem;letter-spacing:.02em}
/* líneas verticales que laten (eco de las barras del emblema) */
@keyframes beamV{0%,100%{opacity:0;transform:translateY(-7%)}50%{opacity:.4;transform:translateY(7%)}}
.beam{transform:none;width:1px;animation:beamV 7s ease-in-out infinite;animation-delay:var(--d,0s);filter:none}
.fx-beams::before{background:conic-gradient(from 0deg,transparent 0 80%,rgb(var(--glow-rgb)/.13) 90%,transparent 100%)}
