path d=%22M545.0 320 V234.1%22/%3E%3Cpath d=%22M556.0 320 V199.1%22/%3E%3Cpath d=%22M567.0 320 V201.4%22/%3E%3Cpath d=%22M578.0 320 V201.5%22/%3E%3Cpath d=%22M589.0 320 V137.1%22/%3E%3Cpath d=%22M611.0 320 V184.3%22/%3E%3Cpath d=%22M622.0 320 V116.7%22/%3E%3Cpath d=%22M644.0 320 V117.3%22/%3E%3Cpath d=%22M655.0 320 V127.9%22/%3E%3Cpath d=%22M688.0 320 V36.0%22/%3E%3Cpath d=%22M699.0 320 V123.6%22/%3E%3Cpath d=%22M710.0 320 V126.7%22/%3E%3Cpath d=%22M732.0 320 V164.9%22/%3E%3Cpath d=%22M743.0 320 V134.9%22/%3E%3Cpath d=%22M754.0 320 V170.1%22/%3E%3Cpath d=%22M787.0 320 V157.8%22/%3E%3Cpath d=%22M798.0 320 V199.3%22/%3E%3Cpath d=%22M809.0 320 V179.9%22/%3E%3Cpath d=%22M820.0 320 V157.1%22/%3E%3Cpath d=%22M831.0 320 V148.1%22/%3E%3Cpath d=%22M842.0 320 V149.0%22/%3E%3Cpath d=%22M853.0 320 V111.5%22/%3E%3Cpath d=%22M864.0 320 V97.8%22/%3E%3Cpath d=%22M875.0 320 V56.1%22/%3E%3Cpath d=%22M886.0 320 V134.0%22/%3E%3Cpath d=%22M897.0 320 V139.5%22/%3E%3Cpath d=%22M908.0 320 V140.8%22/%3E%3Cpath d=%22M919.0 320 V135.2%22/%3E%3Cpath d=%22M930.0 320 V191.0%22/%3E%3Cpath d=%22M941.0 320 V211.3%22/%3E%3Cpath d=%22M952.0 320 V210.6%22/%3E%3Cpath d=%22M963.0 320 V176.3%22/%3E%3Cpath d=%22M974.0 320 V222.8%22/%3E%3Cpath d=%22M985.0 320 V240.9%22/%3E%3Cpath d=%22M996.0 320 V235.3%22/%3E%3Cpath d=%22M1007.0 320 V232.6%22/%3E%3Cpath d=%22M1029.0 320 V239.2%22/%3E%3Cpath d=%22M1040.0 320 V239.6%22/%3E%3Cpath d=%22M1062.0 320 V229.6%22/%3E%3Cpath d=%22M1073.0 320 V239.7%22/%3E%3Cpath d=%22M1084.0 320 V242.3%22/%3E%3Cpath d=%22M1117.0 320 V218.1%22/%3E%3Cpath d=%22M1128.0 320 V212.6%22/%3E%3Cpath d=%22M1139.0 320 V242.6%22/%3E%3Cpath d=%22M1150.0 320 V209.7%22/%3E%3Cpath d=%22M1161.0 320 V191.9%22/%3E%3Cpath d=%22M1183.0 320 V178.9%22/%3E%3Cpath d=%22M1194.0 320 V156.1%22/%3E%3C/g%3E%3Cpath d=%22M0 319.5 H1200%22 stroke=%22%23cfb565%22 stroke-opacity=%22.35%22 stroke-width=%221%22/%3E%3C/svg%3E") repeat-x left bottom/1200px 100%;opacity:.5;animation:skyPan 140s linear infinite}
.hero::after{opacity:1;-webkit-mask:linear-gradient(90deg,transparent,#000 50%,transparent) no-repeat -40% 0/38% 100%;mask:linear-gradient(90deg,transparent,#000 50%,transparent) no-repeat -40% 0/38% 100%;animation:skyPan 140s linear infinite,skyScan 9s ease-in-out infinite alternate}
@keyframes skyPan{to{background-position-x:-1200px}}
@keyframes skyScan{to{-webkit-mask-position:140% 0;mask-position:140% 0}}
/* leyenda vertical de la portada del portafolio */
.hero__bg::before{content:"Haciendo tus proyectos realidad desde 2022";position:absolute;right:3.2%;top:46%;writing-mode:vertical-rl;transform:translateY(-50%);font:500 .66rem/1 var(--font-display);letter-spacing:.55em;text-transform:uppercase;color:rgb(var(--glow-rgb)/.62);white-space:nowrap;display:none}
@media (min-width:1280px){.hero__bg::before{display:block}}
.hero__in,.scroll-cue{z-index:1}
.scroll-cue{border-color:rgb(var(--glow-rgb)/.5)}

/* --- Rótulos verticales y palabra "fantasma" por sección (como el portafolio) */
.sec{overflow:hidden}
.sec::after{position:absolute;right:-1.5%;top:clamp(2rem,5vw,4rem);font:500 clamp(4.2rem,15vw,14rem)/1 var(--font-display);letter-spacing:.06em;text-transform:uppercase;color:transparent;-webkit-text-stroke:1px rgb(var(--ink-rgb)/.075);pointer-events:none;user-select:none;white-space:nowrap}
#servicios::after{content:"Servicios"}
#nosotros::after{content:"Nosotros"}
#proyectos::after{content:"Proyectos"}
#ingenieria::after{content:"Ingeniería"}
#proceso::after{content:"Proceso"}
#contacto::after{content:"Contacto"}
.sec::before{position:absolute;left:1.2rem;top:6rem;writing-mode:vertical-rl;font:500 .64rem/1 var(--font-display);letter-spacing:.55em;text-transform:uppercase;color:var(--muted);opacity:.7;display:none}
#servicios::before{content:"DIIA · Servicios"}
#nosotros::before{content:"DIIA · Sobre nosotros"}
#proyectos::before{content:"DIIA · Proyectos arquitectónicos"}
#ingenieria::before{content:"DIIA · Ingeniería en instalaciones"}
#proceso::before{content:"DIIA · Proceso"}
#contacto::before{content:"DIIA · Contacto"}
@media (min-width:1400px){.sec::before{display:block}}
.sec>.container{position:relative;z-index:1}

/* --- Servicios --------------------------------------------------------------- */
.grid-cards{counter-reset:svc}
.card{counter-increment:svc;background:var(--surface);border-color:rgb(var(--ink-rgb)/.1)}
.card::after{content:"0" counter(svc);position:absolute;top:1.3rem;right:1.5rem;font:500 .72rem/1 var(--font-display);letter-spacing:.3em;color:var(--muted)}
.card h3{font-weight:500;letter-spacing:.01em}
.card:hover{border-color:rgb(var(--glow-rgb)/.6)}
.card__ico{border-radius:2px;background:rgb(var(--glow-rgb)/.1)}
.card__link{font:600 .72rem/1 var(--font-display);letter-spacing:.16em;text-transform:uppercase}
.card--wide{--text:#f6f1e3;--muted:#b9b09a;color:var(--text);background:radial-gradient(120% 140% at 0% 0%,#1c1810,#070707 62%);border-color:rgb(207 181 101/.35)}
.card--wide .card__ico{background:rgb(207 181 101/.14)}
.card--wide .card__link,.card--wide .ticks .ico{color:var(--gold)}

/* --- Sobre nosotros / stats --------------------------------------------------- */
