/%3E%3Cpath d=%22M420.0 240 V132.1%22/%3E%3Cpath d=%22M429.0 240 V146.8%22/%3E%3Cpath d=%22M447.0 240 V171.1%22/%3E%3Cpath d=%22M456.0 240 V171.5%22/%3E%3Cpath d=%22M483.0 240 V187.4%22/%3E%3Cpath d=%22M492.0 240 V188.4%22/%3E%3Cpath d=%22M519.0 240 V179.3%22/%3E%3Cpath d=%22M528.0 240 V188.8%22/%3E%3Cpath d=%22M537.0 240 V184.0%22/%3E%3Cpath d=%22M546.0 240 V186.1%22/%3E%3Cpath d=%22M555.0 240 V187.8%22/%3E%3Cpath d=%22M564.0 240 V190.3%22/%3E%3Cpath d=%22M573.0 240 V186.1%22/%3E%3Cpath d=%22M582.0 240 V187.6%22/%3E%3Cpath d=%22M600.0 240 V188.2%22/%3E%3Cpath d=%22M609.0 240 V190.6%22/%3E%3Cpath d=%22M618.0 240 V191.7%22/%3E%3Cpath d=%22M627.0 240 V177.6%22/%3E%3Cpath d=%22M654.0 240 V144.9%22/%3E%3Cpath d=%22M663.0 240 V180.4%22/%3E%3Cpath d=%22M672.0 240 V188.3%22/%3E%3Cpath d=%22M681.0 240 V190.5%22/%3E%3Cpath d=%22M699.0 240 V192.1%22/%3E%3Cpath d=%22M708.0 240 V188.7%22/%3E%3Cpath d=%22M717.0 240 V187.0%22/%3E%3Cpath d=%22M735.0 240 V192.2%22/%3E%3Cpath d=%22M744.0 240 V173.9%22/%3E%3Cpath d=%22M753.0 240 V137.9%22/%3E%3Cpath d=%22M762.0 240 V145.2%22/%3E%3Cpath d=%22M780.0 240 V137.9%22/%3E%3Cpath d=%22M789.0 240 V172.4%22/%3E%3Cpath d=%22M798.0 240 V183.5%22/%3E%3Cpath d=%22M807.0 240 V175.8%22/%3E%3Cpath d=%22M816.0 240 V179.9%22/%3E%3Cpath d=%22M825.0 240 V156.4%22/%3E%3Cpath d=%22M834.0 240 V116.0%22/%3E%3Cpath d=%22M843.0 240 V160.2%22/%3E%3Cpath d=%22M852.0 240 V138.7%22/%3E%3Cpath d=%22M861.0 240 V94.5%22/%3E%3Cpath d=%22M870.0 240 V133.0%22/%3E%3Cpath d=%22M897.0 240 V105.4%22/%3E%3C/g%3E%3Cpath d=%22M0 239.5 H900%22 stroke=%22%23cfb565%22 stroke-opacity=%22.35%22 stroke-width=%221%22/%3E%3C/svg%3E") repeat-x left bottom/900px 100%;animation:skyPan2 120s linear infinite}
@keyframes skyPan2{to{background-position-x:900px}}
.badge{border-radius:2px;background:linear-gradient(135deg,var(--gold),var(--gold-deep));color:#14110a}
.badge strong{font-weight:500;letter-spacing:-.02em}
.stat__v{font-weight:500}
.stat__l{letter-spacing:.04em}

/* --- Proyectos (sección propia) ------------------------------------------------ */
.proj-grid{display:grid;gap:1rem}
.proj{position:relative;isolation:isolate;overflow:hidden;display:flex;align-items:flex-end;min-height:26rem;border-radius:var(--r-lg);color:#fff;background:#0b0a08;border:1px solid rgb(var(--ink-rgb)/.08)}
.proj__media{position:absolute;inset:-7% 0;z-index:-2;will-change:transform}
.proj__media img{width:100%;height:100%;max-width:none;object-fit:cover;transition:transform 1.8s var(--ease),filter 1s}
.proj:hover .proj__media img{transform:scale(1.07)}
.proj::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgb(0 0 0/.55) 0%,transparent 24%,rgb(5 5 5/.5) 56%,rgb(5 5 5/.95) 100%)}
.proj::before{content:"";position:absolute;inset:0;z-index:0;pointer-events:none;border:1px solid transparent;border-radius:inherit;transition:border-color .6s}
.proj:hover::before{border-color:rgb(207 181 101/.55)}
.proj__no{position:absolute;left:1.4rem;top:1.25rem;font:500 .74rem/1 var(--font-display);letter-spacing:.3em;color:var(--champagne);text-shadow:0 1px 10px rgb(0 0 0/.85)}
.proj__where{position:absolute;right:1.3rem;top:1.1rem;padding:.45rem .75rem;font:500 .62rem/1 var(--font-display);letter-spacing:.22em;text-transform:uppercase;border:1px solid rgb(255 255 255/.28);background:rgb(7 7 7/.35);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.proj__body{position:relative;width:100%;padding:clamp(1.3rem,2.6vw,2rem);padding-top:5rem}
.proj__tag{font:500 .64rem/1.4 var(--font-display);letter-spacing:.3em;text-transform:uppercase;color:var(--gold)}
.proj__name{margin:.55rem 0 .35rem;font:500 clamp(1.3rem,2.2vw + .6rem,2.1rem)/1.15 var(--font-display);letter-spacing:.22em;text-transform:uppercase;color:#fff}
.proj__loc{font:500 .72rem/1.4 var(--font-display);letter-spacing:.14em;text-transform:uppercase;color:rgb(255 255 255/.72)}
.proj__txt{margin-top:.9rem;max-width:34rem;font-size:.95rem;line-height:1.6;color:rgb(255 255 255/.84)}
.sec-cta{display:flex;flex-direction:column;align-items:center;gap:1.3rem;margin-top:clamp(2.2rem,5vw,3.6rem);text-align:center}
.sec-cta p{font:500 clamp(1.05rem,1.4vw + .8rem,1.4rem)/1.35 var(--font-display);letter-spacing:.01em;color:var(--text)}
@media (min-width:640px){
  .proj-grid{grid-template-columns:repeat(2,1fr)}
  .proj--a,.proj--w{grid-column:span 2}
  .proj{min-height:28rem}
}
@media (min-width:960px){
  .proj-grid{grid-template-columns:repeat(12,1fr);gap:1.1rem}
  .proj--a{grid-column:span 7;min-height:34rem}
  .proj--b{grid-column:span 5;min-height:34rem}
  .proj--c,.proj--d,.proj--e{grid-column:span 4;min-height:30rem}
  .proj--w{grid-column:span 12;min-height:34rem}
  .proj--x,.proj--y{grid-column:span 6;min-height:28rem}
  .proj--w .proj__txt{max-width:40rem;font-size:1.02rem}
}

/* --- Ingeniería en instalaciones (bloque oscuro con plano animado) ------------- */
.sec--ing{background:radial-gradient(90% 60% at 85% 0%,rgb(207 181 101/.1),transparent 60%),var(--bg)}
.ing-top{display:grid;gap:2.6rem;align-items:center;margin-bottom:clamp(2.6rem,6vw,4.6rem)}
.ing-copy .lead{margin-top:1.1rem}
.disc{display:grid;gap:0;margin-top:2rem;border-top:1px solid var(--border-strong)}
.disc li{display:flex;align-items:baseline;gap:1.2rem;padding:.95rem .2rem;border-bottom:1px solid var(--border-strong);transition:padding .5s var(--ease),background .4s,color .4s}
.disc b{font:500 .74rem/1 var(--font-display);letter-spacing:.3em;color:var(--gold)}
.disc span{font:500 1.02rem/1.3 var(--font-display);letter-spacing:.06em}
.disc li:hover{padding-left:1rem;background:rgb(var(--glow-rgb)/.07)}
.blueprint{position:relative;overflow:hidden;margin:0;padding:clamp(.7rem,2vw,1.2rem);border-radius:var(--r-lg);background:#0b0a08;border:1px solid rgb(var(--glow-rgb)/.32);box-shadow:0 40px 90px -40px rgb(var(--glow-rgb)/.45)}
.blueprint img{width:100%;height:auto;border-radius:calc(var(--r-lg) - 4px);filter:invert(1) sepia(1) saturate(2.2) hue-rotate(2deg) brightness(1.05) contrast(1.15)}
.blueprint::before{content:"";position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(rgb(207 181 101/.07) 1px,transparent 1px),linear-gradient(90deg,rgb(207 181 101/.07) 1px,transparent 1px);background-size:34px 34px}
.blueprint::after{content:"";position:absolute;left:0;right:0;top:0;height:2px;background:linear-gradient(90deg,transparent,var(--glow),transparent);box-shadow:0 0 22px 4px rgb(var(--glow-rgb)/.55);animation:scanY 6s ease-in-out infinite alternate}
@keyframes scanY{from{transform:translateY(0)}to{transform:translateY(calc(var(--bh,26rem)))}}
.blueprint{--bh:22rem}
.blueprint figcaption{position:relative;margin-top:.9rem;font:500 .62rem/1.5 var(--font-display);letter-spacing:.24em;text-transform:uppercase;color:var(--muted);text-align:center}
@media (min-width:960px){.ing-top{grid-template-columns:1fr 1fr;gap:5rem}.blueprint{--bh:30rem}}

/* --- Proceso / FAQ / CTA / contacto -------------------------------------------- */
.step h3{font-weight:500}
.step__n{border-radius:2px;font-weight:500;letter-spacing:.1em}
.step.is-in .step__n{color:#14110a}
.faq{border-radius:2px}
.faq summary{font-weight:500}
.cta-card{border-radius:var(--r-lg)}
.cta-card h2{font-weight:500}
.cta-card::after{border-radius:calc(var(--r-lg) - 1.5px)}
.form,.info-list li,.map{border-radius:var(--r-lg)}
.field label{letter-spacing:.12em;text-transform:uppercase;font-size:.7rem}
.info-list small{letter-spacing:.2em}

/* --- Footer --------------------------------------------------------------------- */
.footer__about .brand img{height:4.4rem}
.footer__col h4{letter-spacing:.3em}
.footer__bar{letter-spacing:.04em}

/* --- Botón flotante: etiqueta sobria --------------------------------------------- */
.wa-float__label{border-radius:2px;font:500 .7rem/1 var(--font-display);letter-spacing:.14em;text-transform:uppercase}
